#include <algorithm>
#include <iomanip>
#include <iostream>
#include <map>
#include <string>
#include <vector>

struct Trade {
    double price;
    int qty;
};

int main() {
    std::map<std::string, std::vector<Trade>> book;
    std::string sym;
    double price;
    int qty;
    while (std::cin >> sym >> price >> qty) {
        book[sym].push_back({price, qty});
    }
    std::cout << std::fixed << std::setprecision(4);
    for (auto& [s, trades] : book) {
        std::sort(trades.begin(), trades.end(), [](const Trade& a, const Trade& b) { return a.price < b.price; });
        double value = 0;
        double shares = 0;
        for (const Trade& t : trades) {
            value += t.price * t.qty;
            shares += t.qty;
        }
        std::cout << s << ' ' << trades.size() << ' ' << value / shares << ' '
                  << trades.front().price << ' ' << trades.back().price << '\n';
    }
    return 0;
}

