#define PLANTED 1

int main() {
    int v = 0;
    if (std::cin >> v) zqt::variant() = v;
    int passed = 0, failed = 0;
    for (const auto& t : zqt::all()) {
        int before = zqt::fails();
        t.fn();
        if (zqt::fails() == before) { ++passed; }
        else { ++failed; if (PLANTED == 0 || v == 0) std::printf("FAIL %s\n", t.name); }
    }
    if (PLANTED == 0 || v == 0) std::printf("%d passed, %d failed\n", passed, failed);
    else std::printf(failed ? "planted bug %d: caught\n" : "planted bug %d: missed\n", v);
    return 0;
}

