// Tests for max_drawdown(px), which is supplied.
// Worst fall from a running peak,
// as a fraction: 0.25 for 25%.

TEST(worst_fall_from_running_peak) {
    std::vector<double> px{100.0, 120.0, 90.0, 130.0, 104.0};
    double dd = max_drawdown(px);
    CHECK_CLOSE(dd, 0.25, 1e-12);   // 120 down to 90
}

TEST(rising_prices_have_no_drawdown) {
    std::vector<double> px{100.0, 101.0, 103.5};
    CHECK_CLOSE(max_drawdown(px), 0.0, 1e-12);
}

TEST(empty_and_single_price_are_zero) {
    CHECK_CLOSE(max_drawdown({}), 0.0, 1e-12);
    CHECK_CLOSE(max_drawdown({100.0}), 0.0, 1e-12);
}

